import{describe,it,expect,beforeEach}from"vitest";import{districts,achievementBadges,gameModes,getDistrictById,getRandomQuestion,evaluateAnswer,checkUnlockedBadges,getHighScores,saveHighScore}from"../../frontend/guess-up-district/guess-up-district.js";const REQUIRED_DISTRICT_FIELDS=["id","name","division","headquarters","odop","landmarks","clues"];describe("UP District Dataset Integrity",()=>{it("contains at least 20 prominent UP districts",()=>{expect(districts.length).toBeGreaterThanOrEqual(20)}),it("every district object contains all required fields with valid types",()=>{districts.forEach((e,t)=>{REQUIRED_DISTRICT_FIELDS.forEach(s=>{expect(e,`District at index ${t} missing field ${s}`).toHaveProperty(s),"landmarks"===s||"clues"===s?(expect(Array.isArray(e[s])).toBe(!0),expect(e[s].length).toBeGreaterThan(0)):(expect(typeof e[s]).toBe("string"),expect(e[s].trim().length).toBeGreaterThan(0))})})}),it("all district IDs and names are unique",()=>{const e=districts.map(e=>e.id),t=districts.map(e=>e.name);expect(new Set(e).size).toBe(e.length),expect(new Set(t).size).toBe(t.length)}),it("retrieves district profile by ID or name",()=>{const e=getDistrictById("varanasi");expect(e).toBeDefined(),expect(e.name).toBe("Varanasi");const t=getDistrictById("Agra");expect(t).toBeDefined(),expect(t.id).toBe("agra")})}),describe("Game Modes Definition",()=>{it("defines all 4 required game modes",()=>{expect(gameModes).toHaveProperty("easy"),expect(gameModes).toHaveProperty("medium"),expect(gameModes).toHaveProperty("hard"),expect(gameModes).toHaveProperty("timed")}),it("easy mode presents 3 clues and no strict timer",()=>{expect(gameModes.easy.cluesShown).toBe(3),expect(gameModes.easy.timePerQuestion).toBe(0)}),it("hard mode presents 1 clue and a 15s timer",()=>{expect(gameModes.hard.cluesShown).toBe(1),expect(gameModes.hard.timePerQuestion).toBe(15)})}),describe("Question Generator Engine",()=>{it("generates a question with 4 options and clues",()=>{const e=getRandomQuestion("easy");expect(e).not.toBeNull(),expect(e).toHaveProperty("correctDistrict"),expect(e).toHaveProperty("options"),expect(e.options.length).toBe(4),expect(e.options.map(e=>e.id)).toContain(e.correctDistrict.id)}),it("excludes specified district IDs when requested",()=>{const e=["varanasi","agra","lucknow"],t=getRandomQuestion("easy",e);expect(e).not.toContain(t.correctDistrict.id)})}),describe("Answer Evaluator Engine",()=>{it("evaluates correct answer with score and bonus",()=>{const e=districts[0],t=evaluateAnswer("Varanasi",e,10,"easy",!1);expect(t.isCorrect).toBe(!0),expect(t.scoreEarned).toBeGreaterThan(0)}),it("deducts penalty when hint is used",()=>{const e=districts[0],t=evaluateAnswer("Varanasi",e,0,"easy",!1),s=evaluateAnswer("Varanasi",e,0,"easy",!0);expect(s.scoreEarned).toBeLessThan(t.scoreEarned)}),it("evaluates incorrect answer with 0 score",()=>{const e=districts[0],t=evaluateAnswer("Agra",e,10,"easy",!1);expect(t.isCorrect).toBe(!1),expect(t.scoreEarned).toBe(0)})}),describe("Achievement Badges Engine",()=>{it("defines 6 unlockable achievement badges",()=>{expect(achievementBadges.length).toBe(6)}),it("unlocks UP Explorer badge on first correct answer",()=>{const e=checkUnlockedBadges({correctCount:1,streak:1,score:100,mode:"easy"}).map(e=>e.id);expect(e).toContain("badge_first_correct")}),it("unlocks Speed Demon badge in timed mode with 5+ correct",()=>{const e=checkUnlockedBadges({correctCount:5,streak:2,score:600,mode:"timed"}).map(e=>e.id);expect(e).toContain("badge_timed_hero")})}),describe("High Score Storage",()=>{beforeEach(()=>{"undefined"!=typeof localStorage&&localStorage.clear()}),it("returns default 0 high scores when empty",()=>{const e=getHighScores();expect(e).toHaveProperty("easy",0)}),it("saves new high score record",()=>{if("undefined"!=typeof localStorage){const e=saveHighScore("easy",500);expect(e).toBe(!0);const t=getHighScores();expect(t.easy).toBe(500);const s=saveHighScore("easy",700);expect(s).toBe(!0),expect(getHighScores().easy).toBe(700);const o=saveHighScore("easy",300);expect(o).toBe(!1),expect(getHighScores().easy).toBe(700)}})});